exports.resolve=function(tables){
 return exports.cards.map(card=>{
  const from=tables.bells[card.from.toLowerCase()],to=tables.bells[card.to.toLowerCase()];
  if(!from||!to||from.world!==to.world)throw Error('Survey endpoints unresolved: '+card.id);
  const endpoint=bell=>({id:bell.id,name:bell.name,area:bell.area,p:{x:bell.at[0],y:bell.at[1],z:bell.at[2]}});
  return {...card,revision:card.revision||exports.revision,world:from.world,start:endpoint(from),end:endpoint(to)};
 });
};
